"""Private Danek1996 reader/source ledger. No Site, source or queue writes."""
from pathlib import Path
from datetime import datetime,timezone
import hashlib,json,re

OUT=Path(__file__).resolve().parent
B=OUT.parent
SID='danek1996'
DOI='10.1021/cm9503137'
PREFIX='danek-1996-'
RECORDS={key:PREFIX+key for key in ['znse-overgrowth','bare-dot-film','overcoated-dot-film','seed-preparation','electrospray-dispersion','characterization','no-seed-control','no-dezn-control','high-temperature-overgrowth','annealing-control','solution-characterization','film-characterization']}
def read(p):return json.loads(p.read_text(encoding='utf-8'))
def sha(p):return hashlib.sha256(p.read_bytes()).hexdigest()
def loc(p,section):return f'Main PDF p. {p}, printed p. {172+p}, {section}'
def ev(p,section):return {'source_id':SID,'document_role':'main','pdf_page':p,'printed_page':172+p,'locator':loc(p,section)}
SECTIONS={k:{'id':k,'title':v,'items':[]} for k,v in [('precursors','Precursors'),('protocol','Synthesis protocol'),('structures','Final structures'),('properties','Properties'),('intuition','Chemical intuition'),('sources','Sources and limitations')]}
def item(sec,key,title,text,page,where,records=(),cohorts=(),kind='reported_source_fact',notes=(),extra=(),facts=()):
    evidence=[ev(page,where)]+[ev(p,w) for p,w in extra]
    v={'id':key,'title':title,'text':text,'claim_type':kind,'sample_scope':{'cohort_keys':list(cohorts),'state':title,'physical_batch_id':None,'link_limit':'Source-defined cohorts remain distinct. A shared material formula, shell ratio, core size or measurement technique does not establish the same preparation, vial, film or physical specimen.'},'evidence':evidence,'source_locators':[e['locator'] for e in evidence],'canonical_links':[{'record_id':RECORDS[r],'json_pointer':'','relation':'Proposed source-context link, pending canonical sample/operation audit.'} for r in records],'notes':list(notes),'facts':list(facts),'training_eligible':False}
    SECTIONS[sec]['items'].append(v);return v

def content():
    item('precursors','solvent-materials','Solvents and received materials',
      'The received-material list specifies HPLC-grade hexane (Mallinckrodt), electronic-grade methanol (Mallinckrodt), butanol (Mallinckrodt), anhydrous pyridine and acetonitrile (Aldrich), TOP (Fluka), anhydrous nonane (Aldrich), and electronic-grade selenium (Aezar). The paper does not identify the butanol isomer or give water assays. These materials serve different preparation, purification and delivery steps; their presence in the list does not imply that all enter every reaction.',2,'Experimental Section, Materials',records=('seed-preparation','znse-overgrowth','electrospray-dispersion'),notes=('Chemical identities should retain source naming; do not silently convert butanol into a particular isomer.',))
    item('precursors','organometallic-materials','Zinc, cadmium and selenium sources',
      'Solution-overgrowth DEZn is supplied by Aldrich and passed through a 0.2 µm PTFE filter. Dimethylcadmium from Organometallics, Inc. is vacuum-transferred before use in the cited CdSe preparation. A 1.0 M TOPSe stock is prepared by the method cited as reference 10; its complete preparation is not restated here. For matrix deposition the paper separately lists electronic-grade hydrogen selenide (Solkatronic) and electronic-grade DEZn (Texas Alkyls), used as received. Preserve the two DEZn supply/use contexts.',2,'Experimental Section, Materials',records=('seed-preparation','znse-overgrowth','bare-dot-film','overcoated-dot-film'),notes=('The article explicitly cautions that DEZn is highly pyrophoric. Preserve this source warning with the material and dosing operation.','The reference-10 precursor synthesis is not reconstructed from this paper alone.'))
    item('precursors','core-dispersion','CdSe seeds and initial overgrowth dispersion',
      'The standard shell-growth preparation uses approximately 100 mg of purified, size-selected CdSe nanocrystals. After methanol precipitation and centrifugation, the particles are transferred to a glovebox and redispersed in 10 mL TOP containing 0.5 mmol TOPSe. An unspecified small amount of anhydrous nonane may be added to assist redispersion. This initial selenium charge is separate from TOPSe later delivered with DEZn.',2,'Synthesis of CdSe/ZnSe Nanocrystals',records=('znse-overgrowth','seed-preparation'),cohorts=('standard-overgrowth',),notes=('No single initial CdSe diameter applies to all figures. Approximately 4.0 nm, approximately 3.5 nm and approximately 3.7 nm cores appear in different cohorts.','The reported seed mass does not explicitly distinguish inorganic CdSe from ligand-bearing particle mass; glovebox gas identity is not stated.'))
    item('precursors','feed-stock','Equimolar ZnSe-precursor feed',
      'In the glovebox, equimolar DEZn and TOPSe are combined in 10 mL TOP and filtered through a 0.2 µm PTFE syringe filter. The absolute precursor amounts and feed concentration are not specified. The solution is dosed at approximately 0.3 mL/min, but the total delivered volume depends on the desired overgrowth. Neither an exact feed molarity nor a total reaction duration can be recovered from the stated stock volume.',2,'Synthesis of CdSe/ZnSe Nanocrystals',records=('znse-overgrowth',),cohorts=('standard-overgrowth',))
    item('precursors','delivery-dispersion','Pyridine/acetonitrile delivery dispersion',
      'Bare or overcoated pyridine-capped particles are reprecipitated with hexane, centrifuged, transferred to a glovebox, redispersed in anhydrous pyridine and filtered at 0.2 µm. The CdSe concentration is adjusted to approximately 3 mg/mL before dilution with a twofold excess of anhydrous acetonitrile. The source does not explicitly define the excess basis or provide the measured final concentration; the 3 mg/mL value is on a CdSe basis, not necessarily total core-plus-shell solids.',2,'Preparation of the Nanocrystal Dispersions for ES-OMCVD',records=('electrospray-dispersion','bare-dot-film','overcoated-dot-film'),cohorts=('film-feed-bare','film-feed-overcoated'))
    item('precursors','gas-substrate-materials','Atmospheres, carrier gas and substrates',
      'Shell overgrowth uses Ar, pyridine dispersions are stored under N2, and the separate annealing experiment uses flowing He. Ultrahigh-purity H2 from Matheson is purified through a palladium cell and carries the deposition precursors/aerosol. ES-OMCVD substrates are degreased glass microscope slides (Fisher); the degreasing chemistry is not specified. Silicon supports, nickel/carbon TEM grids and added carbon films belong to characterization preparation rather than the nanocrystal synthesis.',2,'Materials; ES-OMCVD Synthesis; Chemical Composition',records=('znse-overgrowth','bare-dot-film','overcoated-dot-film','annealing-control','characterization'),extra=((3,'Electron Microscopy and X-ray Diffraction'),(4,'Structural Characterization')))
    item('precursors','measurement-standards','Optical and elemental-analysis standards',
      'Absolute solution photoluminescence estimates use rhodamine 590 in methanol as the comparison. X-ray fluorescence uses laboratory-grown OMCVD ZnSe films and CdSe powder of 99.99% purity (Alfa) as standards. These are calibration materials, not additional synthesis ingredients or measurements of the same particle specimen. The paper supplies no formula-level identity or quantum-yield certificate for the rhodamine standard.',2,'Optical Characterization and Chemical Composition',records=('characterization','solution-characterization','film-characterization'))

    item('protocol','seed-route','Upstream CdSe synthesis and size selection',
      'The authors prepare size-selected CdSe by controlled growth in a TOP/TOPO mixture using reference 10. They purify by repeated methanol precipitation and hexane redispersion, then narrow the distribution by size-selective precipitation from hexane/methanol mixtures. This paper does not restate the core-growth injection quantities, temperature programme, precursor synthesis or detailed fractionation conditions. Keep the cited upstream preparation as a partial supporting procedure.',2,'Synthesis of CdSe/ZnSe Nanocrystals',records=('seed-preparation',),cohorts=('upstream-seeds',),notes=('The existing Murray1993 atlas entry may be linked as a distinct inspected source, but its alternatives must not be silently assigned to this preparation.',))
    item('protocol','shell-preparation','Seed loading and inert transfer',
      'Precipitate the selected CdSe sample with methanol, isolate it by centrifugation, transfer it to the glovebox and prepare the TOP/TOPSe dispersion described above. If needed, add anhydrous nonane to assist redispersion. Filter through 0.2 µm PTFE, transfer to an Ar-backfilled flask and heat to 150 °C. The synthesis is described as Schlenk-line work under Ar. Stirring speed, pressure, transfer timing, filter recovery and exact nonane dose are unreported.',2,'Synthesis of CdSe/ZnSe Nanocrystals',records=('znse-overgrowth',),cohorts=('standard-overgrowth',))
    item('protocol','shell-dosing','Controlled precursor dosing and monitoring',
      'Dose the separately filtered DEZn/TOPSe feed continuously into the hot, stirred seed dispersion with a syringe pump at approximately 0.3 mL/min. Follow overgrowth by UV/vis absorption and stop after the desired precursor amount. Methods give 150 °C; Results describe successful overgrowth at 150–160 °C. Preserve both scopes rather than treating the range as a measured temperature ramp. No recipe-specific total dose, exposure duration or feed concentration is supplied.',2,'Synthesis of CdSe/ZnSe Nanocrystals',records=('znse-overgrowth',),cohorts=('standard-overgrowth','growth-figure1'),extra=((3,'Results and Discussion, Synthesis'),))
    item('protocol','shell-quench-workup','Cooling, alcoholysis and purification',
      'After dosing, cool to room temperature and add approximately 5 mL butanol to alcoholyze unreacted DEZn. Precipitate the overcoated particles with hexane and separate them by centrifugation. Repeated pyridine redispersion followed by hexane precipitation both purifies the product and exchanges its surface ligands. Solvent volumes other than the reported butanol amount, cycle count, centrifuge settings, timing and isolated yield are absent.',2,'Synthesis of CdSe/ZnSe Nanocrystals',records=('znse-overgrowth',),cohorts=('standard-overgrowth',))
    item('protocol','ligand-storage','Pyridine exchange and storage',
      'The authors report quantitative TOP-to-pyridine cap exchange during purification, supported by phosphorus falling below the AES detection limit; the numerical limit is not given. Particles larger than about 5 nm precipitate nearly quantitatively when hexane is added to their TOP dispersion, while approximately 4–5 nm particles remain more dispersible. Pyridine redisperses the precipitate. Store under N2 in anhydrous pyridine; the text reports stability for several months under inert gas but changing dispersibility after air exposure.',2,'Synthesis of CdSe/ZnSe Nanocrystals',records=('znse-overgrowth','solution-characterization'),cohorts=('standard-overgrowth','ligand-storage-context'),extra=((4,'Solubility and purification discussion'),))
    item('protocol','electrospray-preparation','Dispersion dilution and degassing',
      'After the pyridine dispersion is adjusted and diluted with acetonitrile, degas through several cycles on a high-vacuum line. The printed order is “thaw–pump–freeze”; keep that source wording rather than silently replacing it with a conventional order. Acetonitrile is introduced to stabilize electrospray operation. A custom liquid-handling system attached to the reactor is mentioned without construction details. Cycle count, vacuum, temperatures and reservoir volume are not specified.',2,'Preparation of the Nanocrystal Dispersions for ES-OMCVD',records=('electrospray-dispersion',),cohorts=('film-feed-bare','film-feed-overcoated'),notes=('The source wording is evidence, not a fully validated operational SOP.',))
    item('protocol','electrospray-operation','Electrospray atomization',
      'A positive capillary electrode and grounded ring counterelectrode are held at 4.5 kV dc. A syringe pump supplies the nanocrystal dispersion at 17 µL/min. The aerosol enters the growth zone in 1000 sccm H2. Both the electrospray and reactor are maintained at 600 Torr. Electrode dimensions, spacing, droplet distribution, transport residence time and standard-volume reference conditions are unreported; the apparatus is referred to reference 2a.',2,'ES-OMCVD Synthesis',records=('bare-dot-film','overcoated-dot-film'),cohorts=('film-common-deposition',))
    item('protocol','matrix-deposition','ZnSe matrix deposition and film stack',
      'Hydrogen selenide at 20 µmol/min and DEZn at 1 µmol/min, carried in H2, supply the ZnSe matrix. Films grow on degreased glass at substrate temperatures in the 150–270 °C study range. First deposit approximately 0.1 µm ZnSe, then approximately 1 µm composite, and finish with approximately 0.1 µm ZnSe. The sandwich is intended to bury the nanocrystals. Layer-specific deposition times, film-growth rates and gas-switching details are not reported.',2,'ES-OMCVD Synthesis',records=('bare-dot-film','overcoated-dot-film'),cohorts=('film-common-deposition',))
    item('protocol','film-variant-assignments','Film variants and temperature assignments',
      'Figures 7–8 compare bare and passivated feeds at 150 and 200 °C, then compare bare dots deposited at 250 °C with overcoated dots deposited at 270 °C. Their overcoated feed is labelled [ZnSe/CdSe] = 0.4. Figure 10 instead uses approximately 3.7 nm initial cores, ratio 4.0 and 200 °C deposition. Figure 11 concerns a coverage series at 200 and 260 °C. These are separate figure-defined cohorts; the two high-temperature panels are not a matched-temperature pair.',6,'Figure 7 and film-composite discussion',records=('bare-dot-film','overcoated-dot-film','film-characterization'),cohorts=('films-figure7-8','film-figure10','films-figure11'),extra=((7,'Figures 8–10'),(8,'Figure 11')))
    item('protocol','comparative-experiments','Comparison experiments and treatment scope',
      'Three comparisons probe the overgrowth mechanism: reaction without CdSe seeds, reaction without DEZn dosing, and overgrowth near 200 °C. Their complete matched conditions are not restated. A separate solution-deposited particle film on glass is annealed in He for about 30 min; the text gives approximately 400 °C but Figure 4 gives approximately 450 °C. This annealed film is not an ES-OMCVD composite or a demonstrated improvement protocol.',3,'Synthesis, comparative experiments',records=('no-seed-control','no-dezn-control','high-temperature-overgrowth','annealing-control'),cohorts=('no-seed','no-dezn','high-temperature','annealed-solution-film'),extra=((4,'Structural Characterization and Figure 4'),))

    item('structures','electron-microscopy-method','Electron microscopy and specimen preparation',
      'HRTEM uses a Topcon EM002B at 200 kV. A drop of diluted pyridine dispersion contacts a nickel/carbon grid briefly, excess is rinsed with solvent, and an additional carbon film improves electron-beam stability. Dilution, contact duration, rinse solvent identity and carbon thickness are unreported. Microscopy concerns prepared aliquots and does not establish a unique physical-specimen identity across the optical, AES and diffraction datasets.',2,'Electron Microscopy',records=('characterization','solution-characterization'),cohorts=('growth-figure1','structural-ratio2p5'),extra=((3,'Electron Microscopy continuation'),))
    item('structures','figure1-size-series','Figure 1 particle-size series',
      'The embedded HRTEM table gives a: 4.0 nm (s = ±12%), b: 4.4 nm (±11%), c: 5.0 nm (±13%) and d: 6.8 nm (±13%). These are labelled stages of the overgrowth/absorption series, not four independently specified recipes. The body describes the initial spread as approximately 10%, differing from the table’s ±12%. Preserve the table and its original notation; particle counts and sampling uncertainty are absent.',3,'Figure 1 embedded table and Synthesis discussion',records=('znse-overgrowth','solution-characterization'),cohorts=('growth-figure1',),notes=('The enlarged table crop is a view of Figure 1, not an additional experiment or separate source table.','Do not assign feed dose or duration to a–d without reported evidence.'),facts=tuple({'label':'Figure 1 '+label,'value':diameter,'unit':'nm','status':'reported','qualifier':f's = ±{spread}% as printed','basis':'HRTEM size table; not a synthesis target'} for label,diameter,spread in [('a',4.0,12),('b',4.4,11),('c',5.0,13),('d',6.8,13)]))
    item('structures','hrtem-interface','Particle morphology and interface limits',
      'HRTEM shows growth from nearly spherical starting particles to slightly irregular approximately 6.8 nm particles with aspect ratio about 1.3. Figure 2 concerns derivatized particles with [ZnSe/CdSe] approximately 2.5 and retains its 5.0 nm scale bar. Coherent lattice fringes in some particles are consistent with epitaxial overgrowth, but the interface location is not resolved. Missing peripheral diffraction contrast in some particles is interpreted as possible amorphous or disordered overlayer.',3,'Synthesis, morphology discussion',records=('solution-characterization',),cohorts=('growth-figure1','structural-ratio2p5'),extra=((4,'Structural Characterization and Figure 2'),))
    item('structures','xrd-measurement','Diffraction measurement and reference patterns',
      'Powder XRD uses a Rigaku 300 rotating-anode instrument in Bragg configuration with Cu Kα radiation. Precipitated particles are spread on a (100) Si wafer. Figure 3 compares approximately 6.8 nm overcoated particles (ratio approximately 2.5) with approximately 4.0 nm CdSe and with wurtzite ZnSe/CdSe reference lines. The overcoated pattern has broad features that do not coincide with either reference. Reference lines do not constitute measured phase refinement or atomic coordinates for these products.',3,'X-ray Diffraction',records=('characterization','solution-characterization'),cohorts=('structural-ratio2p5',),extra=((4,'Figure 3 and diffraction discussion'),),notes=('No peak fitting, lattice constants, refined CIF, SAED image or digitized diffraction trace is supplied.',))
    item('structures','elemental-methods','Bulk and surface composition methods',
      'X-ray fluorescence measures Zn/Cd using a Diano V generator with Cr anode and an HNU Si:Li detector. Nanocrystal specimens are prepared by evaporating a few droplets of pyridine dispersion on Si. AES uses a Perkin-Elmer model 660 microprobe with a 5 keV primary beam. The quoted roughly 1.0 nm Auger escape depth is the basis for a surface-sensitive interpretation; no raw AES or XRF spectrum is plotted.',2,'Chemical Composition',records=('characterization','solution-characterization'),cohorts=('composition-ratio4p8',),extra=((5,'Structural Characterization continuation'),))
    item('structures','surface-bulk-ratio','Shell nonuniformity from surface/bulk comparison',
      'For an approximately 3.5 nm core cohort, bulk [ZnSe/CdSe] is 4.8 whereas AES gives 7.0. The authors consider 7.0 too low for a symmetric core/shell structure with an approximately 1.3 nm overlayer and infer nonuniform coverage. The 1.3 nm is geometry/model context, not a resolved TEM shell thickness. This cohort cannot be automatically identified with the approximately 4.0→6.8 nm structural series or every solution-optics ratio-4.8 specimen.',5,'Structural Characterization continuation',records=('solution-characterization',),cohorts=('composition-ratio4p8',),kind='reported_result_and_author_interpretation')
    item('structures','study-composition-range','Study-level composition range',
      'The abstract summarizes layered-particle [ZnSe/CdSe] ratios from zero to approximately 5.0. This is a product-composition range across the study, not a precursor feed ratio, a continuous tested optimization grid, or a uniformly measured shell-thickness interval. Surface-sensitive AES ratios and matrix-containing film composition must remain separately labelled.',1,'Abstract',records=('solution-characterization',),kind='reported_study_context',extra=((2,'Chemical Composition'),(5,'Structural Characterization continuation')))
    item('structures','annealing-evidence','Annealing test and diffraction alternatives',
      'Figure 4 compares a ratio-2.5 particle film before and after He annealing and marks a calculated bulk Zn0.7Cd0.3Se bandgap as a reference. The shorter-wavelength absorption after annealing is used by the authors to argue that the original broad diffraction pattern was not already due to extensive alloying. Poor crystallinity and lattice-spacing variations caused by mismatch remain alternative explanations. The paper explicitly calls for detailed diffraction simulation; it does not supply one.',4,'Structural Characterization and Figure 4',records=('annealing-control','solution-characterization'),cohorts=('annealed-solution-film','structural-ratio2p5'),kind='reported_result_and_author_interpretation',notes=('Keep the approximately 400 °C body / approximately 450 °C caption conflict. Do not invent an intermediate corrected temperature.','The plotted alloy bandgap is a calculation/reference, not a measured atomic structure or proven uniform composition of each annealed particle.'))
    item('structures','dispersion-size-limit','Size-dependent dispersibility',
      'The procedure reaches particles of approximately 7 nm. Above that size, instability and precipitation of the TOP dispersion prevent uniform further overgrowth. This is the authors’ observed process limitation, not a calibrated maximum attainable diameter for all conditions. No particle-count distribution, isolated mass yield or global synthesis-success rate is supplied.',3,'Synthesis, final paragraph',records=('solution-characterization','znse-overgrowth'),cohorts=('size-stability-context',),extra=((4,'Solubility discussion'),))

    item('properties','optical-instruments','Optical acquisition and yield definitions',
      'Absorption uses an HP 8452 diode-array instrument; photoluminescence and excitation spectra use a Spex Fluorolog-2 with front-face collection. Corrections account for PMT response and source spectral flux. Absolute solution yields compare integrated particle emission in pyridine with rhodamine 590 in methanol. Film yields are relative band-edge-emission measures, with absorbed excitation estimated from rear-side transmission detected by an Oriel Si photodiode. A liquid-He-cooled Janis cryostat supplies low-temperature film measurements.',2,'Optical Characterization',records=('characterization','solution-characterization','film-characterization'),notes=('Absolute solution quantum yield, relative film emission, normalized spectra and curve multipliers are distinct quantities.'))
    item('properties','growth-absorption','Absorption during overgrowth and controls',
      'Figure 1 shows increasing UV absorption during growth while the CdSe band edge changes little. The early lowest-energy absorption maximum red-shifts by approximately 2 nm. The comparison without DEZn argues against simple CdSe Ostwald ripening as its cause. Near 200 °C, an initial approximately 2 nm blue shift precedes the red shift, interpreted as possible interfacial alloying. These are source-described shifts, not absolute peak positions reconstructed from curves.',3,'Synthesis and Figure 1',records=('solution-characterization','no-dezn-control','high-temperature-overgrowth'),cohorts=('growth-figure1','no-dezn','high-temperature'),kind='reported_result_and_author_interpretation')
    item('properties','seed-free-product','Product without CdSe seeds',
      'Without CdSe nuclei, the precursors react slowly to produce a white, hexane-soluble precipitate with a sharp absorption feature at 320 nm. The authors suggest a ZnSe analogue of cited approximately 1.5 nm CdS/CdSe clusters. Neither a 1.5 nm ZnSe diameter nor a proven cluster structure is measured here. This side product is reported absent when CdSe seeds are present.',3,'Synthesis, comparative experiment without CdSe',records=('no-seed-control',),cohorts=('no-seed',),kind='reported_observation_and_tentative_identity')
    item('properties','solution-pl-series','Solution absorption and photoluminescence series',
      'The optical series is sampled from one preparation at successive overgrowth stages and measured in pyridine. Figure 5 labels a as bare CdSe, b as ratio 3.6, c as 4.3 and d as 4.8, with approximate yields 0.05%, 0.4%, 0.4% and 0.3%, respectively, under 480 nm excitation. The prose gives a broader bare-particle range of approximately 0–0.05%. The source supports relative yield differences in this cohort; it does not establish each ratio as a fully specified independent synthesis.',5,'Optical Characterization and Figure 5',records=('solution-characterization',),cohorts=('solution-optics',),facts=tuple({'label':'Figure 5 '+label+' solution yield','value':value,'unit':'%','status':'reported','approximate':True,'basis':f'{ratio}; pyridine dispersion; excitation 480 nm'} for label,ratio,value in [('a','bare CdSe',0.05),('b','[ZnSe/CdSe] 3.6',0.4),('c','[ZnSe/CdSe] 4.3',0.4),('d','[ZnSe/CdSe] 4.8',0.3)]))
    item('properties','solution-spectral-changes','Band-edge changes in solution',
      'For the solution series, passivation shifts the absorption maximum by approximately 4 nm and emission by approximately 2–4 nm to longer wavelength. Both bare and coated samples retain an approximately 10 nm Stokes shift and the same stated emission width, without a numerical FWHM. A second absorption feature disappears and short-wavelength absorption strengthens. Interpretations concerning confinement and surface-sensitive excited states belong to the authors; no absolute spectral peaks or uncertainty values are read from the plotted curves.',5,'Optical Characterization',records=('solution-characterization',),cohorts=('solution-optics',),kind='reported_result_and_author_interpretation')
    item('properties','solution-ple','Solution photoluminescence excitation',
      'Figure 6 detects emission at 570 nm and normalizes all curves at 550 nm. It uses the bare/3.6/4.3/4.8 solution series from Figure 5. Short-wavelength excitation becomes more efficient after overgrowth, while the ratio-4.8 sample shows a reduction relative to thinner coatings. These normalized excitation efficiencies are not additional absolute photoluminescence yields or measured shell-thickness values.',5,'Figure 6',records=('solution-characterization',),cohorts=('solution-optics',),extra=((6,'Optical Characterization continuation'),))
    item('properties','film-room-temperature','Room-temperature film emission',
      'Figure 7 uses 480 nm excitation and contrasts bare-dot films dominated by broad deep-level emission with ratio-0.4 coated-dot films dominated by band-edge emission. The bare series red-shifts by approximately 10 nm from 150 to 200 °C deposition, then returns toward approximately 550 nm at 250 °C as its relative band-edge yield drops by roughly an order of magnitude. The coated series shows an approximately 4 nm blue shift and weak deep-level emission even at 270 °C. Curve scaling and minor initial-size differences prevent treating overlaid normalized traces as absolute yields.',6,'Film-composite discussion and Figure 7',records=('film-characterization','bare-dot-film','overcoated-dot-film'),cohorts=('films-figure7-8',),kind='reported_result_and_author_interpretation')
    item('properties','film-10k','Film emission at 10 K',
      'Figure 8 compares the same labelled temperature/coating categories at 10 K with 480 nm excitation. Bare-dot films show strong broad trap emission; coated-dot films remain band-edge dominated. For coated films, increasing deposition temperature from 150 to 270 °C produces an approximately 8 nm blue shift without a reported change in FWHM. The paper discusses approximately 5–60 min thermal exposure for individual embedded particles depending on film depth; this is not a specified common deposition time or dwell setting.',7,'Figure 8 and preceding discussion',records=('film-characterization',),cohorts=('films-figure7-8',),kind='reported_result_and_author_interpretation',notes=('Original curve-specific multipliers are retained in the figure; do not compare uncorrected drawn heights as yield values.',))
    item('properties','bare-film-ple','Excitation spectra of the bare-dot film',
      'Figure 9 concerns a bare-dot composite deposited at 200 °C. Detection is at 554 nm for 300 K and at 546 and 710 nm for 10 K. The band-edge excitation spectra follow CdSe absorption in the 460–520 nm region and weaken at shorter wavelength as the matrix absorbs. The low-temperature trap-emission excitation feature supports an origin in CdSe dots. Arrows denote cubic-ZnSe bandgap references; they are not a refined phase measurement of the composite.',7,'Figure 9 and film photoexcitation discussion',records=('film-characterization',),cohorts=('film-figure9',),kind='reported_result_and_author_interpretation')
    item('properties','coated-film-ple','Excitation spectra of the coated-dot film',
      'Figure 10 is a separate composite with approximately 3.7 nm initial CdSe dots, [ZnSe/CdSe] = 4.0 and deposition at 200 °C. Detection wavelengths are 576 nm at 300 K and 570 nm at 10 K. Excitation features in approximately the 480–550 nm region and a shorter-wavelength matrix edge are described. The authors infer that direct dot absorption, rather than matrix-to-dot transfer, populates emissive states. Do not replace its ratio 4.0 by the 0.4 printed for Figures 7–8.',7,'Figure 10 and film photoexcitation discussion',records=('film-characterization',),cohorts=('film-figure10',),kind='reported_result_and_author_interpretation')
    item('properties','film-coverage-yield','Relative film yield and calculated coverage',
      'Figure 11 compares films deposited at 200 and 260 °C under 500 nm excitation. The horizontal coverage scale is calculated from composition and initial particle size assuming a symmetric core/shell geometry. The source reports more than a tenfold improvement near approximately 0.6 monolayer and approximately 100-fold near approximately 3 monolayers. The vertical scale is relative band-edge yield, not an absolute quantum-yield percentage. No individual curve points or exact monolayer values have been digitized.',8,'Figure 11 and coverage discussion',records=('film-characterization',),cohorts=('films-figure11',),kind='reported_result_with_author_derived_geometry',notes=('A geometry-derived mean coverage must not be relabelled as an atomically counted, uniform shell; AES/HRTEM indicate nonuniformity/disorder.',))

    item('intuition','passivation-rationale','Why passivate before incorporation?',
      'The authors aim to preserve the optical benefits of size-controlled CdSe while embedding it in a process-compatible semiconductor matrix. Prior ES-OMCVD films had agglomeration, grain boundaries and weak, thermally unstable luminescence. Preforming ZnSe on each dot is intended to provide electronic passivation of traps and chemical protection during deposition. The proposed electrical/doping/device uses and approximately 1.8–2.5 eV tuning context are motivation, not electrical-device measurements in this article.',1,'Introduction and Abstract',kind='author_rationale_and_cited_context',extra=((2,'Introduction continuation'),),notes=('References 1–4, 9 and the earlier ES-OMCVD papers are contextual; their uninspected data do not fill this paper’s recipe gaps.',))
    item('intuition','overgrowth-not-exchange','Why heterogeneous overgrowth?',
      'The paper contrasts heterogeneous precipitation with cation displacement. Its displayed aqueous reaction Zn²⁺(aq) + CdSe(s) ⇌ Cd²⁺(aq) + ZnSe(s) has quoted ΔG° = +56.0 kJ/mol and is considered unfavorable, motivating overgrowth from organometallic precursors. That thermodynamic comparison is not the actual net reaction in TOP. Prior inverse-micelle and layered-semiconductor studies motivate the choice but are not recipes independently reviewed here.',3,'Synthesis, unnumbered displacement reaction',kind='author_rationale_and_cited_context',notes=('The reference reaction contains aqueous ions; do not present it as a measured mechanism or exact stoichiometric equation for DEZn/TOPSe chemistry.',))
    item('intuition','slow-delivery','Why slow precursor delivery and optical monitoring?',
      'Slow, steady dosing is chosen to favor heterogeneous growth on the existing CdSe seeds and limit homogeneous ZnSe nucleation. Increased UV absorption, preserved CdSe band edge, particle enlargement and the no-seed comparison support the authors’ overgrowth interpretation together. Absorption shifts serve as a practical probe of core integrity; none of these observations alone resolves a uniform shell or specifies a kinetic rate law.',3,'Synthesis discussion',kind='author_mechanistic_interpretation')
    item('intuition','solvent-surface-compatibility','Why TOP, pyridine and acetonitrile?',
      'TOP supports organometallic overgrowth and coordinates the particles. The contrasting dispersibility in hexane and pyridine provides a purification and cap-exchange route; pyridine-capped particles are chosen for compatibility with the ZnSe OMCVD chemistry. Acetonitrile dilution stabilizes electrospray operation. These functional explanations follow the source; binding constants, surface coverage, solvent conductivity and quantitative colloidal-stability models are absent.',2,'Introduction continuation and Experimental Section',kind='author_rationale_and_reported_function',extra=((4,'Solubility and ligand-exchange discussion'),))
    item('intuition','interface-defects','Why is solution luminescence still modest?',
      'Despite better emission than pyridine-capped bare dots, coated solution particles reach only approximately 0.3–0.4% yield. The authors relate this limitation to shell/interface disorder and propose that relatively defect-free particles dominate the emission. Approximately 10% TOP/TOPO-capped CdSe yield is a reference-10 comparison, not a same-batch control measured here. Broad XRD can also reflect mismatch strain, so poor crystallinity is an interpretation with alternatives.',5,'Optical Characterization and structural continuation',kind='author_interpretation_and_cited_context',extra=((4,'Structural Characterization'),))
    item('intuition','excitation-transfer','Excitation transfer and shell-thickness tradeoff',
      'Improved short-wavelength solution excitation is interpreted as carrier transfer from the attached ZnSe region to the CdSe core; separate ZnSe particles would instead screen excitation light. The decrease at the highest reported optical-series ratio is attributed to increasing defects with thicker mismatch-strained coverage. Cited superlattice examples and an approximately four-monolayer critical-thickness discussion are analogies, not a measured critical shell thickness for these colloids.',6,'Optical Characterization continuation',kind='author_interpretation_and_cited_context',notes=('Do not turn the superlattice comparison into a prospective four-monolayer synthesis target.',))
    item('intuition','film-mechanisms','Interpreting film spectral changes',
      'For bare-dot composites, the authors connect red shifts with agglomeration/growth or energy transfer and high-temperature blue shifts with alloying. In coated films, weaker trap emission and stable band-edge response are interpreted as electronic and chemical protection. Low-temperature and excitation spectra help locate traps in the CdSe component. Matrix recombination at defects/grain boundaries is proposed to suppress matrix-fed excitation. These are interpretations, not independently resolved microscopic rate constants.',6,'Thin-film composite discussion',kind='author_interpretation',extra=((7,'Low-temperature and photoexcitation discussion'),))
    item('intuition','outlook','Proposed improvements and open questions',
      'The authors propose improving shell coherence and the CdSe/ZnSe interface, potentially through annealing in a coordinating solvent, to increase the fraction of well-passivated particles. That suggestion cites earlier work and is not tested here as a successful optimized protocol. Their conclusions emphasize passivation for deposition above 200 °C and stable crystalline matrices. Missing atomistic interface evidence, complete process endpoints and recipe-to-specimen joins remain useful targets for subsequent work.',6,'Optical Characterization, outlook',kind='author_outlook_and_review_gap',extra=((8,'Conclusions'),),notes=('The separate approximately 400/450 °C He film anneal is an alloying diagnostic, not evidence for the proposed coordinating-solvent improvement.',))

    item('sources','source-conflicts','Source distinctions and conflicts',
      'Preserve the Figure 1 initial relative spread of ±12% beside the body’s approximately 10%; Methods 150 °C beside the Results 150–160 °C overgrowth scope; and Figure 4 approximately 450 °C beside the body’s approximately 400 °C anneal. Figures 7–8 use coated ratio 0.4 while Figure 10 uses 4.0; their distinct captions define different cohorts, not an automatically corrected decimal. The high-temperature film comparison is bare 250 °C versus coated 270 °C.',3,'Synthesis and Figure 1',kind='source_conflict_and_scope_assessment',extra=((2,'Experimental Section'),(4,'Figure 4'),(6,'Figure 7'),(7,'Figures 8 and 10')))
    item('sources','reporting-gaps','Missing information and limits',
      'SI is not located or verified. Major gaps include complete upstream precursor/core recipes; absolute DEZn/TOPSe feed loading and delivered dose; dosing endpoint time; many solvent volumes; centrifugation conditions and cycle counts; precise gas purity/standard-volume bases; electrode/reactor dimensions; deposition timing and layer-growth rates; exact figure-to-preparation joins; per-measurement sample counts and uncertainty; instrument acquisition settings; raw spectra; refined lattice/atomic coordinates; and isolated synthesis yield. Missing fields are not zero values or failed reactions.',2,'Experimental Section',kind='review_gap_assessment',extra=((3,'Results and Figure 1'),(4,'Structural Characterization'),(5,'Optical Characterization'),(6,'Film discussion'),(7,'Film spectroscopy'),(8,'Conclusions')))
    item('sources','scope-and-reuse','Scope of the source review',
      'This contribution is based on eight supplied main-article pages. Two byte-identical local copies are one source content. Figure 1 contains an embedded size table; there is no standalone numbered table, no Raman or SAED pattern, no plotted AES/XRF spectrum, and no measured atomic-coordinate file. Original spectra/images remain available without inventing values from curves. References are inventoried as citations; publication, canonical review and training eligibility require their own explicit gates.',1,'Title and source identity',kind='review_scope_assessment',extra=((3,'Figure 1 and unnumbered reaction'),(8,'Closing matter'),))

REF_ROLES={1:'Quantum-dot optical properties and applications; five cited review subentries',2:'Earlier ES-OMCVD composite fabrication and apparatus; subentry 2a is the cited equipment description',3:'Electrospray technique background',4:'Earlier degradation in silicon-based composites',5:'ZnS-on-CdS passivation precedent',6:'ZnS-on-CdSe and surface-sensitive composition precedent',7:'Layered CdS/HgS systems and optical passivation context',8:'Silicon surface-passivation precedent, including separately reviewed Littau1993 in subentry a',9:'Compatibility of particle derivatization with ZnSe OMCVD chemistry',10:'Cited TOPSe/CdSe preparation, size selection, cap exchange and optical-quality benchmark; complete upstream procedure not restated',11:'Semiconductor overlayer formation and lattice-mismatch diffraction context',12:'Ion-displacement chemistry context',13:'Prior inverse-micelle CdSe/ZnSe core/shell approach and surface analysis',14:'DEZn/TOPSe chemistry used for ZnSe epilayers',15:'CdS cluster analogy for tentative no-seed product identity',16:'Excited-state assignments; source lists the work as submitted',17:'Misfit relaxation and optical degradation in strained superlattices; not a measured colloidal critical thickness',18:'Coordinating-solvent annealing precedent invoked as future improvement'}
def references():
    found=[]
    for page in range(1,9):
        t=(B/f'plain-page-{page}.txt').read_text(encoding='utf-8')
        matches=list(re.finditer(r'^\((\d{1,2})\)\s',t,re.M))
        for j,m in enumerate(matches):
            n=int(m.group(1));tail=t[m.end():matches[j+1].start() if j+1<len(matches) else len(t)]
            tail=re.split(r'(?m)^Figure \d+\.|^\d{3}\s*Chem\.|^Thin-Film CdSe',tail)[0]
            citation=' '.join(tail.split())
            assert citation and n in REF_ROLES
            item('sources',f'reference-{n}',f'Reference {n}',citation,page,f'References, entry {n}',kind='citation_only',notes=(REF_ROLES[n],'The cited work was not independently read in this task; missing experimental parameters are not imported.'))
            v={'reference_number':n,'citation_reader_item_id':f'reference-{n}','role':REF_ROLES[n],'source_locators':[loc(page,f'References, entry {n}')],'evidence_class':'citation_only','cited_work_independently_reviewed_in_this_task':False,'import_experimental_evidence':False}
            if n==8:v['existing_atlas_context']={'subentry':'a','source_id':'littau1993','doi':'10.1021/j100108a019','note':'Separate source review; not imported into this record.'}
            if n==10:v['existing_atlas_context']={'source_id':'murray1993','doi':'10.1021/ja00072a025','note':'Separate source review; no automatic choice of its protocol variants for this source.'}
            found.append(v)
    assert sorted(x['reference_number'] for x in found)==list(range(1,19))
    return sorted(found,key=lambda x:x['reference_number'])

